      i: 0, j: 0, resto: 0, dipinto: 0,
      fatto: function(){ return this.dipinto; },
      segna: function(q){ this.dipinto = q; },
      finita: function(){ return this.i >= this.linee.length; },
      azzera: function(){ this.i = 0; this.j = 0; this.resto = 0; this.dipinto = 0; },
